options.helpers:
context.handlebars.registerHelper('sourceHealth', function(rows, now) {
  const number = Number(now) / 1000;
  const collected = (rows || []).find(row => row.field === 'collected');
  const stamp = collected ? Number(collected.value) : NaN;
  const stale = !Number.isFinite(stamp) || !Number.isFinite(number) || number - stamp > 600;
  const result = [{name:'Collector', state:stale ? 'error' : 'ok',
    text:!Number.isFinite(stamp) ? 'missing collection timestamp' : stale ? 'stale · last collection over 10m ago' : 'current'}];
  const names = {t3:'T3 providers',t3_usage:'T3 usage','opencode-go':'OpenCode Go'};
  for (const [source, name] of Object.entries(names)) {
    const info = (rows || []).find(row => row.source === source && row.field === 'info');
    const missing = !info || stale;
    result.push({name, state:missing || info.status !== 'ok' ? 'error' : 'ok',
      text:missing ? 'missing or stale reading' : info.status === 'ok' ? 'current' : 'unavailable · ' + (info.reason || info.status) + (source === 't3' && info.reason === 'unsupported' ? ' · #470' : '')});
  }
  return result;
});

