options.styles:
.gx{font:12px/1.3 Inter,system-ui,sans-serif;color:#e6e8ee;container-type:inline-size;width:100%}
.gx *{box-sizing:border-box}
.gx .in{background:#181a20;border:1px solid #262932;border-radius:8px;padding:10px 12px}
.gx header{display:flex;flex-wrap:wrap;align-items:baseline;gap:2px 10px;margin:0 0 4px}
.gx header b{font-size:12px;letter-spacing:.05em;text-transform:uppercase;color:#c9ccd3}
.gx header span{font-size:11px;color:#8b8f99}
.gx ol{list-style:none;margin:0;padding:0}
.gx .ic{flex:none;width:20px;height:20px;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700}
.gx .good{--c:#5fb878}.gx .ok{--c:#5b9bd5}.gx .warn{--c:#e0a03a}.gx .bad{--c:#e66767}.gx .out{--c:#e66767}.gx .held{--c:#b08cf0}.gx .unk,.gx .idle{--c:#8b8f99}
.gx .hatch,.gx .unk .bar,.gx .bar.unk,.gx .pa.unk{background:repeating-linear-gradient(135deg,#2a2d36 0 4px,#3a3e49 4px 8px)}
.gx .bar{display:block;position:relative;height:8px;border-radius:4px;background:#2a2d36;overflow:hidden}
.gx .bar .fill{position:absolute;left:0;top:0;bottom:0;border-radius:4px;background:var(--c,#5b9bd5)}
.gx .bar.estimated .fill{background:repeating-linear-gradient(135deg,var(--c) 0 4px,#2a2d36 4px 6px)}
.gx .bar.out{background:repeating-linear-gradient(135deg,#3b2327 0 4px,#4c2b30 4px 8px)}
.gx .bar .tick{position:absolute;top:0;bottom:0;width:2px;background:#fff;opacity:.85}
.gx .pa{position:relative;flex:none;width:76px;height:8px;border-radius:4px;background:#2a2d36}
.gx .pa:after{content:"";position:absolute;left:50%;top:-2px;bottom:-2px;width:1px;background:#9aa1ad}
.gx .pa.unk:after{display:none}
.gx .pa i{position:absolute;top:0;bottom:0;border-radius:3px;background:var(--c)}
.gx .pill{font-style:normal;font-size:10px;font-weight:700;letter-spacing:.03em;text-transform:uppercase;padding:1px 6px;border-radius:9px;color:#111;background:var(--c);white-space:nowrap;flex:none}
.gx .pill.unk,.gx .pill.idle{color:#d6d9e0;background:#3a3e49}
.gx .lane .ls+.ls{margin-top:12px;padding-top:8px;border-top:1px solid #2f323c}
.gx .lane li.r{display:flex;align-items:flex-start;gap:8px;padding:7px 0;border-top:1px solid #23262e}
.gx .lane li.r:first-child{border-top:0}
.gx .lane .n{flex:none;width:16px;text-align:right;font-weight:700;color:#8b8f99;font-variant-numeric:tabular-nums;line-height:20px}
.gx .lane li.first .n{color:#5fb878}
.gx .lane .bd{flex:1;min-width:0}
.gx .lane .l1,.gx .lane .l2{display:flex;flex-wrap:wrap;align-items:center;gap:2px 7px;min-width:0}
.gx .lane .l1{min-height:20px}
.gx .lane .l1 .pa{flex:none;width:56px}
.gx .lane .sw{display:none}
.gx .lane .nm{font-size:13px;font-weight:600;flex:none}
.gx .lane .md{flex:1 1 12ch;min-width:0;overflow-wrap:anywhere;color:#8b8f99}
.gx .lane .big{flex:none;margin-left:auto;font-size:14px;font-weight:700;font-variant-numeric:tabular-nums;color:var(--c)}
.gx .lane .big.unk,.gx .lane .big.held{font-size:11px;font-weight:500;color:#8b8f99;font-style:italic}
.gx .lane .l2{margin-top:4px;font-size:11px;color:#9aa1ad}
.gx .lane .pt{flex:0 0 auto;overflow:hidden}
.gx .lane .pv{font-weight:700;color:var(--c);font-variant-numeric:tabular-nums}
.gx .lane .pv.unk{color:#8b8f99;font-weight:500;font-style:italic}
.gx .lane .wn{flex:0 1 auto;min-width:0;margin-left:auto;color:#8b8f99}
.gx .lane .pt .short{display:none}
.gx .lane .more{margin-top:6px;padding-top:6px;border-top:1px solid #23262e;font-size:11px;color:#8b8f99}
.gx .lane .none{padding:14px 0;color:#8b8f99}
.gx .tiles{display:grid;grid-template-columns:repeat(12,1fr);gap:8px}
.gx .tile{grid-column:span 3;min-width:0;background:#181a20;border:1px solid #262932;border-radius:8px;padding:10px 12px;display:flex;flex-direction:column;justify-content:center;gap:3px}
.gx .tile.pick{grid-column:span 6}
.gx .tile .k{font-size:11px;letter-spacing:.05em;text-transform:uppercase;color:#8b8f99}
.gx .tile .v{font-size:24px;font-weight:700;line-height:1.15;color:var(--c,#e6e8ee);overflow-wrap:anywhere}
.gx .tile .v .ic{display:inline-flex;vertical-align:middle;margin-right:7px}
.gx .tile .s{font-size:11px;color:#9aa1ad;overflow-wrap:anywhere}
.gx .tile.stat .v{font-size:34px}
.gx .tile.zero .v{color:#8fc98f}
.gx .tile.unk .v{color:#b5b8c0}
.gx .prov li.pr{padding:9px 0;border-top:1px solid #23262e}
.gx .prov li.pr:first-child{border-top:0}
.gx .prov .t{display:flex;flex-wrap:wrap;align-items:center;gap:2px 8px;min-width:0}
.gx .prov .nm{font-size:13px;font-weight:600;flex:none}
.gx .prov .big{margin-left:auto;font-size:16px;font-weight:700;color:var(--c);font-variant-numeric:tabular-nums;flex:none}
.gx .prov .big.unk{font-size:13px;font-weight:600}
.gx .prov .bar{margin-top:6px}
.gx .prov .dt{margin-top:5px;font-size:11px;color:#9aa1ad;overflow-wrap:anywhere}
.gx .prov .dt b{color:var(--c)}
.gx .prov .ch{margin-top:4px;display:flex;flex-wrap:wrap;gap:3px 5px}
.gx .prov .ch span{font-size:10px;padding:1px 6px;border-radius:9px;background:#23262e;color:#aeb6c3;overflow-wrap:anywhere}
.gx .prov .ch span.out{color:#e66767}.gx .prov .ch span.unk{color:#8b8f99;background:repeating-linear-gradient(135deg,#23262e 0 4px,#2e323b 4px 8px)}
.gx .prov .ev{margin-top:5px;font-size:11px;color:#cdb8ff}
.gx .frees li.fr{padding:6px 0;border-top:1px solid #23262e;min-width:0}
.gx .frees li.fr:first-child{border-top:0}
.gx .frees .r1{display:flex;flex-wrap:wrap;align-items:center;gap:2px 8px;min-width:0}
.gx .frees .nm{flex:1 1 9em;min-width:0;font-weight:600;font-size:13px;overflow-wrap:anywhere}
.gx .frees .mc{flex:0 1 auto;font-size:11px;color:#8b8f99;overflow-wrap:anywhere}
.gx .frees .st{flex:none;min-width:92px;text-align:right;font-size:11px;color:var(--c);font-weight:600;white-space:nowrap}
.gx .frees .fb{flex:none;width:54px}
.gx .frees .wy{margin:3px 0 0 28px;font-size:11px;color:#e66767;overflow-wrap:anywhere}
@container (min-width:900px){
 .gx .tile .k{font-size:12px}.gx .tile .s{font-size:12.5px}
 .gx .tile .v{font-size:30px}.gx .tile.stat .v{font-size:46px}.gx .tile .v small{font-size:15px}
 .gx .tile .v .ic{width:26px;height:26px;font-size:15px}
}
@container (max-width:640px){
 .gx .tile.pick{grid-column:span 12}
