 .gx .tile{padding:5px 10px;gap:0}
 .gx .tile .k{font-size:10px;line-height:1.2}
 .gx .tile .v{font-size:16px;line-height:1.15}.gx .tile.stat .v{font-size:22px;line-height:1.1}
 .gx .tile .s{font-size:10.5px;line-height:1.2}
 .gx .tile .v .ic{width:16px;height:16px;font-size:10px;margin-right:6px}
}
@container (max-width:420px){
 .gx .lane .pt .long{display:none}.gx .lane .pt .short{display:inline}
 .gx .lane .pa{width:56px}
 .gx .lane .l1 .pa{display:none}
 .gx .lane li.out .pt{display:none}
 .gx .lane .pt .short{display:none}
 .gx .lane .warn .sw{display:none}
 .gx .lane .pill:not(.good){display:none}.gx .lane .sw{display:inline;color:var(--c);font-weight:600}
 .gx .frees .mc{display:none}
 .gx .frees .st{min-width:0}
}

options.helpers:
// Presentation only. Every number is a collector gauge; this code orders,
// words and colours them and never turns a missing reading into a number.
const PROVIDERS = {
  claude: {name: 'Claude', icon: '✳', bg: '#d97757', fg: '#fff'},
  codex: {name: 'Codex', icon: '⊛', bg: '#e8e8e8', fg: '#111'},
  ollama: {name: 'Ollama', icon: '◉', bg: '#f2f2f2', fg: '#111'},
  'opencode-go': {name: 'OpenCode Go', icon: '{}', bg: '#2b2f3a', fg: '#7dd3fc'},
  antigravity: {name: 'Antigravity', icon: 'A', bg: 'linear-gradient(135deg,#4f8cff,#c86bfa)', fg: '#fff'},
  grok: {name: 'Grok', icon: '⊘', bg: '#000', fg: '#fff'},
  commandCode: {name: 'Command Code', icon: 'C', bg: '#2b2f3a', fg: '#e6e8ee'},
  opencode: {name: 'OpenCode Zen', icon: 'O', bg: '#2b2f3a', fg: '#e6e8ee'},
  'cloudflare-workers-ai': {name: 'Cloudflare'},
  'kilo-keyed': {name: 'Kilo (keyed)', icon: 'K'},
  openrouter: {name: 'OpenRouter'},
  nvidia: {name: 'NVIDIA'},
  ovh: {name: 'OVH'},
  zai: {name: 'Zai'},
  deepseek: {name: 'DeepSeek'},
  orcarouter: {name: 'Orcarouter'},
};
function who(id) {
  const known = PROVIDERS[id] || {};
  const text = String(id || '');
  return {
    name: known.name || text.split(/[-_\s]+/).filter(Boolean).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' '),
    icon: known.icon || text.charAt(0).toUpperCase(),
    bg: known.bg || '#2b2f3a',
    fg: known.fg || '#e6e8ee',
  };
}
function num(value) {
  if (value === null || value === undefined || value === '') { return null; }
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}
function round1(value) { return Math.round(value * 10) / 10; }
// The span until a reset: minutes, hours, then days.
function span(seconds) {
  if (seconds <= 0) { return 'now'; }
  const minutes = Math.max(1, Math.round(seconds / 60));
  if (minutes < 60) { return minutes + 'm'; }
  if (minutes < 2880) { return Math.floor(minutes / 60) + 'h ' + (minutes % 60) + 'm'; }
  return round1(minutes / 1440) + 'd';
}
function back(reset, now) {
  if (reset === null || reset === undefined) { return ''; }
  const left = span(reset - now);
  return left === 'now' ? 'back now' : 'back in ' + left;
}
// The share that is left: a half point is kept, a whole reading has no zero.
function share(left) {
  const tenths = Math.round(left * 1000);
  return (tenths % 10 === 0 ? String(tenths / 10) : (tenths / 10).toFixed(1)) + '%';
}
function signed(points) {
  const value = round1(Math.abs(points));
  return (points > 0 ? '+' : points < 0 ? '−' : '') + value;
}
function clock(seconds) {
  const moment = new Date(seconds * 1000);
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const pad = (n) => String(n).padStart(2, '0');
  return moment.getUTCDate() + ' ' + months[moment.getUTCMonth()] + ' ' + pad(moment.getUTCHours()) + ':' + pad(moment.getUTCMinutes()) + 'Z';
}
// A pace band to a tone and a word. spent is out of quota, never "on pace".
const PACE = {
  ahead: {tone: 'good', word: 'ahead of pace'},
  on_pace: {tone: 'ok', word: 'on pace'},
  behind: {tone: 'warn', word: 'behind pace'},
  far_behind: {tone: 'bad', word: 'overspent'},
  spent: {tone: 'out', word: 'out of quota'},
};
// The bar of Paced Availability: centre line is on pace, right is ahead and
// left is overspent. A missing reading gets no bar and no number.
function paBar(points) {
  if (points === null) { return {known: false, left: 50, width: 0, side: 'unk'}; }
  const half = Math.min(100, Math.abs(points)) / 2;
  return {known: true, left: points < 0 ? 50 - half : 50, width: Math.max(half, 1.5), side: points < 0 ? 'neg' : 'pos'};
}

// Who fills a reading the collector does not publish yet: the sub-issue of the epic.
const FILLED_BY = {claude: '#465', commandCode: '#466'};
function filledBy(provider) { return FILLED_BY[provider] ? ' · ' + FILLED_BY[provider] : ''; }

// ---- Routes: one row per selected route of a lane --------------------------
const ROUTE_FIELDS = {position: 'position', left: 'left', pace: 'pace', resetAt: 'resetAt'};
function readRoutes(rows) {
  const routes = new Map();
  for (const row of rows || []) {
    if (!row || !row.category || !row.provider || !row.model || !ROUTE_FIELDS[row.field]) { continue; }
    const key = [row.category, row.provider, row.model, row.effort || ''].join('|');
    let route = routes.get(key);
    if (!route) { route = {labels: row, n: {}}; routes.set(key, route); }
    route.n[row.field] = num(row.value);
  }
  return Array.from(routes.values());
}
// What a route is, in the order the picker ranks it, and why.
function routeView(route, now) {
  const l = route.labels;
  const n = route.n;
  const inferred = l.window === 'inferred';
  // An inferred window that has seen no limit is not 100%: it is unknown.
  const left = n.left === undefined || n.left === null || (inferred && n.left >= 1) ? null : n.left;
  const pace = PACE[l.pace_state] || null;
  const pa = n.pace === undefined || n.pace === null ? null : n.pace;
  const out = l.state === 'exhausted' || l.state === 'excluded' || l.state === 'unavailable';
  let kind = 'ok';
  let word = '';
  if (l.state === 'exhausted') { kind = 'out'; word = 'Out of quota'; }
  else if (l.state === 'excluded') { kind = 'out'; word = 'Excluded'; }
  else if (l.state === 'unavailable') { kind = 'out'; word = 'Unavailable'; }
  else if (l.state === 'reserved') { kind = 'held'; word = 'Held for review'; }
  else if (l.overspent === 'true' || l.pace_state === 'far_behind') { kind = 'bad'; word = 'Overspent'; }
  else if (l.pace_state === 'behind') { kind = 'warn'; word = 'Behind pace'; }
  else if (left === null && pa === null) { kind = 'unk'; }
  else if (pace) { kind = pace.tone; }
  const reset = n.resetAt === undefined ? null : n.resetAt;
  const provider = who(l.provider);
  const bar = paBar(out ? null : pa);
  return {
    key: [l.category, l.provider, l.model].join(':'),
    provider: l.provider, name: provider.name, icon: provider.icon, bg: provider.bg, fg: provider.fg,
    model: l.display_name || l.model, effort: l.effort || '',
    position: n.position === undefined || n.position === null ? 1e9 : n.position,
    state: l.state, kind: kind, word: word, out: out,
    left: left, leftText: left === null ? '' : share(left),
    // spent routes say 0% left because the quota is gone, not because it is unknown
    // a daily or session window has no pace: only a long window is paced
    paceLong: pa !== null || out || /week|month|quota/i.test(l.window || ''),
    capacity: left === null ? (out ? '' : (inferred ? 'no limit seen' : 'capacity unknown' + filledBy(l.provider))) : share(left) + ' left',
    pa: pa, paText: out || pa === null ? '' : signed(pa), paKnown: bar.known && !out,
    paLeft: bar.left, paWidth: bar.width, paSide: bar.side,
    window: l.window || '', reset: reset,
    when: reset === null ? '' : (out ? back(reset, now) : (span(reset - now) === 'now' ? 'resets now' : 'resets in ' + span(reset - now))),
    estimated: inferred && left !== null,
    free: /^(free|promotion)$/.test(l.billing || ''),
    note: l.state === 'reserved' ? 'review headroom unknown' : '',
  };
}
// The orchestrator is the picker's first orchestrator: the other candidates it lists are not orchestrators.
function configured(rows) {
  const list = (rows || []).filter((row) => row && row.category === 'orchestrator' && row.field === 'position');
  if (!list.length) { return rows; }
  const first = list.reduce((a, b) => (num(b.value) < num(a.value) ? b : a));
  return rows.filter((row) => !row || row.category !== 'orchestrator' || row.provider === first.provider);
}
// An account whose lowest window reads zero is out of quota, whatever its route reading says.
function readAccounts(rows) {
  const windows = new Map();
  for (const row of rows || []) {
    if (!row || !row.account || (row.field !== 'acctLeft' && row.field !== 'acctReset')) { continue; }
    const key = row.account + '|' + (row.quota_id || row.kind || '');
    let entry = windows.get(key);
    if (!entry) { entry = {account: row.account, left: null, reset: null, estimated: row.evidence === 'inferred'}; windows.set(key, entry); }
    if (row.field === 'acctLeft') { entry.left = num(row.value); } else { entry.reset = num(row.value); }
  }
  const out = new Map();
  for (const entry of windows.values()) {
    if (entry.left === null || entry.left > 0) { continue; }
    const known = out.get(entry.account);
    out.set(entry.account, {reset: Math.max(known ? known.reset || 0 : 0, entry.reset || 0) || null,
      estimated: (known ? known.estimated : true) && entry.estimated});
  }
  return out;
}
function laneRows(rows, now, accounts) {
  const views = readRoutes(rows).map((route) => routeView(route, now)).map((view) => {
    const account = accounts && accounts.get(view.provider);
    // The provider's account says it is spent: show that, with the window's reset, not the route's own reading.
    return account && !view.out ? {...view, kind: 'out', out: true, word: 'Out of quota', capacity: '0% left', leftText: '0%', left: 0,
      paKnown: false, paceLong: false, when: account.reset ? back(account.reset, now) : '',
      acctNote: 'account window spent' + (account.estimated ? ' · estimated' : '')} : view;
  }).sort((a, b) => a.position - b.position || (a.name < b.name ? -1 : 1))
    // One row per provider: a provider's other selected routes (the OpenCode Free routes filed under it) follow its first.
    .filter((view, index, list) => list.findIndex((other) => other.provider === view.provider) === index);
  const first = views.findIndex((view) => !view.out && view.kind !== 'held');
  // The rank is the picker's own position among all workers, so a paid worker reads 4th when free routes go first.
  return views.map((view, index) => ({...view, rank: view.position < 1e9 ? view.position : index + 1, first: index === first,
    next: index === first && view.position === 1,
    pace: !view.acctNote && (view.paKnown || (view.kind !== 'unk' && (view.paceLong || !!view.when)))}));
}

// ---- Providers: the account windows -----------------------------------------
function readWindows(rows) {
  const accounts = new Map();
  const entry = (account) => {
    let value = accounts.get(account);
    if (!value) { value = {account: account, windows: new Map(), avail: null, missing: false, learning: false, free: null, reasons: [], announced: null}; accounts.set(account, value); }
    return value;
  };
  for (const row of rows || []) {
    if (!row || !row.account || row.category || row.field === 'acctLeft' || row.field === 'acctReset') { continue; }
    const value = num(row.value);
    const account = entry(row.account);
    if (row.field === 'reported_missing') { if (value === 1) { account.missing = true; } continue; }
    if (row.field === 'availability') { if (value === 1) { account.avail = {state: row.state, basis: row.basis, reason: row.reason}; } continue; }
    if (row.field === 'learning') { if (value === 1) { account.learning = true; } continue; }
    if (row.field === 'free_models') {
      account.free = account.free || {available: 0, unavailable: 0};
      if (row.state === 'available') { account.free.available = value || 0; }
      if (row.state === 'unavailable') { account.free.unavailable = value || 0; }
      continue;
    }
    if (row.field === 'free_reason') { if (value > 0) { account.reasons.push({reason: String(row.reason || ''), count: value, obsolete: row.obsolete === 'true'}); } continue; }
    if (row.field === 'announced') {
      const at = Date.parse(row.reset_at || '') / 1000;
      if (row.confidence === 'confirmed' && Number.isFinite(at) && (!account.announced || at < account.announced)) { account.announced = at; }
      continue;
    }
    if (!row.quota_id && !row.kind) { continue; }
    const key = (row.kind || '') + '|' + (row.quota_id || '');
    let window = account.windows.get(key);
    if (!window) {
      window = {label: String(row.label || '').replace(/^Quota\s*·\s*/, ''), kind: row.kind || '', inferred: row.evidence === 'inferred',
        left: null, expected: null, resetAt: null, order: 99, rolling: false, state: '', pace: null, notUsed: false};
      account.windows.set(key, window);
    }
    if (row.not_used === 'true') { window.notUsed = true; }
    if (row.field === 'left') { window.left = value; }
    else if (row.field === 'expected') { window.expected = value; }
    else if (row.field === 'resetAt') { window.resetAt = value; }
    else if (row.field === 'order') { window.order = value === null ? 99 : value; }
    else if (row.field === 'rolling') { window.rolling = value === 1; }
    else if (row.field === 'pace_state' && value === 1) { window.state = row.state; }
    else if (row.field === 'pace_delta') { window.pace = value; }
  }
  return Array.from(accounts.values());
}
// A window's reading is known unless it is an inferred window that has seen no limit.
function windowKnown(window) {
  return window.left !== null && !(window.inferred && window.left >= 1);
}
function freeWhy(reasons) {
  const groups = new Map();
  for (const entry of reasons || []) {
    const until = entry.reason.match(/until (\d{4}-\d\d-\d\dT[\d:]+Z)/);
    let label;
    if (until) { label = 'cooling until ' + clock(Date.parse(until[1]) / 1000); }
    else if (/not offered/i.test(entry.reason)) { label = 'not offered'; }
    else if (entry.obsolete || /obsolete|deprecated|superseded/i.test(entry.reason)) { label = 'obsolete'; }
    else if (/exclud/i.test(entry.reason)) { label = 'excluded'; }
    else { label = entry.reason.replace(/_/g, ' ').slice(0, 28) || 'unavailable'; }
    groups.set(label, (groups.get(label) || 0) + entry.count);
  }
  return Array.from(groups.entries()).sort((a, b) => b[1] - a[1]).map(([label, count]) => count + ' ' + label);
}
// One provider: its lowest known window leads; unknown windows stay unknown.
function providerView(account, now) {
  const who_ = who(account.account);
  const windows = Array.from(account.windows.values()).sort((a, b) => a.order - b.order);
  const used = windows.filter((w) => !w.notUsed);
  const known = used.filter(windowKnown);
  const unknown = used.filter((w) => !windowKnown(w));
  const view = {account: account.account, name: who_.name, icon: who_.icon, bg: who_.bg, fg: who_.fg,
    kind: 'unk', head: 'Unknown', detail: '', bar: null, chips: [], partial: false, free: account.free,
    sort: 2, announced: account.announced && account.announced > now - 86400 && account.announced < now + 7 * 86400 ? account.announced : null, left: null, pa: null};
  const pool = account.free;
  if (known.length) {
    const lead = known.reduce((a, b) => (b.left < a.left ? b : a));
    const pace = PACE[lead.state] || null;
    const out = lead.left <= 0;
    const longWindow = lead.expected !== null && !lead.rolling && !/session|hour|daily|minute|inferred/i.test(lead.kind);
    view.left = lead.left;
    view.pa = lead.pace;
    view.kind = out ? 'out' : (pace && longWindow ? pace.tone : 'ok');
    view.head = out ? 'Out of quota' : share(lead.left) + ' left';
    view.bar = {width: Math.round(lead.left * 1000) / 10, tick: longWindow ? Math.round(lead.expected * 1000) / 10 : null,
      estimated: lead.inferred};
    const bits = [lead.label];
    if (lead.pace !== null && longWindow && !out) { bits.push((lead.pace < 0 ? '▼ ' : lead.pace > 0 ? '▲ ' : '● ') + signed(lead.pace) + ' Paced Availability'); }
    if (lead.resetAt !== null && !lead.rolling) { bits.push(back(lead.resetAt, now)); }
    if (view.announced) { bits.push('⚡ reset confirmed' + (view.announced > now ? ' in ' + span(view.announced - now) : ' · done')); }
    if (out && lead.pace === null && account.account === 'antigravity') { bits.push('no Paced Availability yet · #468'); }
    view.detail = bits.join(' · ');
    view.chips = used.filter((w) => w !== lead).map((w) => ({label: w.label,
      text: windowKnown(w) ? (w.left <= 0 ? 'out' : share(w.left)) : 'unknown', kind: windowKnown(w) ? (w.left <= 0 ? 'out' : 'ok') : 'unk'}));
    view.partial = unknown.length > 0;
    view.sort = out ? 0 : 1;
  } else if (account.missing) {
    view.head = 'Unknown'; view.detail = 'limits could not be read · collector source failed' + filledBy(account.account);
  } else if (account.avail && account.avail.state === 'unavailable') {
    view.kind = 'out'; view.head = 'Unavailable'; view.detail = account.avail.reason || ''; view.sort = 0;
  } else if (used.length && unknown.length) {
    view.detail = 'no limit seen yet · ' + unknown.length + ' estimated window' + (unknown.length === 1 ? '' : 's');
  } else if (windows.length && !used.length) {
    view.kind = 'idle'; view.head = 'Not used'; view.detail = 'every window is marked not used'; view.sort = 3;
  } else {
    view.detail = (account.learning ? 'no limit published · learning' : 'no limit published · no usage reading') + filledBy(account.account);
  }
  view.notUsed = windows.length - used.length;
  return view;
}

function freeView(account, now) {
  const base = providerView(account, now);
  const counts = account.free || {available: 0, unavailable: 0};
  const blocked = counts.available <= 0 && counts.unavailable > 0;
  const models = counts.available > 0 ? counts.available + ' model' + (counts.available === 1 ? '' : 's') : '';
  if (blocked) {
    return {...base, kind: 'out', head: 'Blocked', bar: null, chips: [], sort: 0, models: '',
      sub: freeWhy(account.reasons).slice(0, 3).join(', ') || counts.unavailable + ' models unavailable'};
  }
  if (base.bar && base.kind !== 'unk') {
    return {...base, sort: base.kind === 'out' ? 0 : 1, models: [models, base.detail].filter(Boolean).join(' · '), sub: ''};
  }
  return {...base, kind: 'unk', head: 'No limit seen', bar: null, chips: [], sort: 2, models: models, sub: ''};
}
function sortViews(views) {
  const share = (view) => (view.left === null ? 2 : view.left);
  return views.sort((a, b) => a.sort - b.sort || share(a) - share(b) || (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
}
const NOW = (value) => (num(value) || 0) / 1000;
const isFreeRoute = (row) => /^(free|promotion)$/.test(row.billing || '');
context.handlebars.registerHelper('laneRows', function(rows, now, lane, limit) {
  const free = lane === 'free';
  const all = laneRows(configured(rows).filter((row) => row && row.category === (lane === 'orchestrator' ? 'orchestrator' : 'worker')
    && (lane === 'orchestrator' || free === isFreeRoute(row))), NOW(now), free ? readAccounts(rows) : null);
  const shown = limit ? all.slice(0, limit) : all;
  return {rows: shown, more: all.length - shown.length, count: all.length};
});
context.handlebars.registerHelper('providerRows', function(rows, now) {
  return sortViews(readWindows(rows).filter((account) => account.account !== 'openrouter').map((account) => providerView(account, NOW(now))).filter((view) => !view.free));
});
context.handlebars.registerHelper('freeRows', function(rows, now) {
  return sortViews(readWindows(rows).filter((account) => account.free || account.avail || account.windows.size).map((account) => freeView(account, NOW(now))));
});
context.handlebars.registerHelper('headline', function(rows, now) {
  rows = configured(rows);
  const at = NOW(now);
  const routes = readRoutes((rows || []).filter((row) => row && row.category)).map((route) => routeView(route, at));
  const pick = (list) => list.sort((a, b) => a.position - b.position).find((view) => !view.out && view.kind !== 'held') || null;
  const orchestrator = pick(routes.filter((r) => r.key.startsWith('orchestrator:')));
  const worker = pick(routes.filter((r) => r.key.startsWith('worker:')));
  const providers = readWindows(rows).filter((account) => account.windows.size || account.missing || account.avail)
    .map((account) => providerView(account, at));
  const free = readWindows(rows).filter((account) => account.free);
  const pickText = (view) => view ? {name: view.name, icon: view.icon, bg: view.bg, fg: view.fg, model: view.model,
    detail: [view.word, view.capacity, view.when].filter(Boolean).join(' · '), kind: view.kind} : null;
  const names = (list) => list.map((view) => view.name);
  const out = providers.filter((view) => view.kind === 'out');
  const over = providers.filter((view) => view.kind === 'bad');
  const behind = providers.filter((view) => view.kind === 'warn');
  const unknown = providers.filter((view) => view.kind === 'unk');
  const blocked = free.map((account) => freeView(account, at)).filter((view) => view.kind === 'out');
  return {orchestrator: pickText(orchestrator), worker: pickText(worker),
    out: {count: out.length + blocked.length, text: names(out.concat(blocked)).join(', ')},
    over: {count: over.length, text: names(over).join(', ')},
    behind: {count: behind.length, text: names(behind).join(', ')},
    unknown: {count: unknown.length, text: names(unknown).join(', ')}};
});

options.styles:
.gx{font:12px/1.3 Inter,system-ui,sans-serif;color:#e6e8ee;container-type:inline-size;width:100%}
.gx *{box-sizing:border-box}
.gx .in{background:#181a20;border:1px solid #262932;border-radius:8px;padding:10px 12px}
.gx header{display:flex;flex-wrap:wrap;align-items:baseline;gap:2px 10px;margin:0 0 4px}
.gx header b{font-size:12px;letter-spacing:.05em;text-transform:uppercase;color:#c9ccd3}
.gx header span{font-size:11px;color:#8b8f99}
.gx ol{list-style:none;margin:0;padding:0}
.gx .ic{flex:none;width:20px;height:20px;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700}
.gx .good{--c:#5fb878}.gx .ok{--c:#5b9bd5}.gx .warn{--c:#e0a03a}.gx .bad{--c:#e66767}.gx .out{--c:#e66767}.gx .held{--c:#b08cf0}.gx .unk,.gx .idle{--c:#8b8f99}
.gx .hatch,.gx .unk .bar,.gx .bar.unk,.gx .pa.unk{background:repeating-linear-gradient(135deg,#2a2d36 0 4px,#3a3e49 4px 8px)}
.gx .bar{display:block;position:relative;height:8px;border-radius:4px;background:#2a2d36;overflow:hidden}
.gx .bar .fill{position:absolute;left:0;top:0;bottom:0;border-radius:4px;background:var(--c,#5b9bd5)}
