.gx .bar.out{background:repeating-linear-gradient(135deg,#3b2327 0 4px,#4c2b30 4px 8px)}
.gx .bar .tick{position:absolute;top:0;bottom:0;width:2px;background:#fff;opacity:.85}
.gx .pa{position:relative;flex:none;width:76px;height:8px;border-radius:4px;background:#2a2d36}
