.gx .tile .k{font-size:11px;letter-spacing:.05em;text-transform:uppercase;color:#8b8f99}
.gx .tile .v{font-size:24px;font-weight:700;line-height:1.15;color:var(--c,#e6e8ee);overflow-wrap:anywhere}
.gx .tile .v .ic{display:inline-flex;vertical-align:middle;margin-right:7px}
.gx .tile .s{font-size:11px;color:#9aa1ad;overflow-wrap:anywhere}
.gx .tile.stat .v{font-size:34px}
.gx .tile.zero .v{color:#8fc98f}
.gx .tile.unk .v{color:#b5b8c0}
.gx .prov li.pr{padding:9px 0;border-top:1px solid #23262e}
.gx .prov li.pr:first-child{border-top:0}
.gx .prov .t{display:flex;flex-wrap:wrap;align-items:center;gap:2px 8px;min-width:0}
.gx .prov .nm{font-size:13px;font-weight:600;flex:none}
.gx .prov .big{margin-left:auto;font-size:16px;font-weight:700;color:var(--c);font-variant-numeric:tabular-nums;flex:none}
.gx .prov .big.unk{font-size:13px;font-weight:600}
.gx .prov .bar{margin-top:6px}
.gx .prov .dt{margin-top:5px;font-size:11px;color:#9aa1ad;overflow-wrap:anywhere}
.gx .prov .dt b{color:var(--c)}
.gx .prov .ch{margin-top:4px;display:flex;flex-wrap:wrap;gap:3px 5px}
.gx .prov .ch span{font-size:10px;padding:1px 6px;border-radius:9px;background:#23262e;color:#aeb6c3;overflow-wrap:anywhere}
.gx .prov .ch span.out{color:#e66767}.gx .prov .ch span.unk{color:#8b8f99;background:repeating-linear-gradient(135deg,#23262e 0 4px,#2e323b 4px 8px)}
.gx .prov .ev{margin-top:5px;font-size:11px;color:#cdb8ff}
.gx .frees li.fr{padding:6px 0;border-top:1px solid #23262e;min-width:0}
.gx .frees li.fr:first-child{border-top:0}
.gx .frees .r1{display:flex;flex-wrap:wrap;align-items:center;gap:2px 8px;min-width:0}
.gx .frees .nm{flex:1 1 9em;min-width:0;font-weight:600;font-size:13px;overflow-wrap:anywhere}
.gx .frees .mc{flex:0 1 auto;font-size:11px;color:#8b8f99;overflow-wrap:anywhere}
.gx .frees .st{flex:none;min-width:92px;text-align:right;font-size:11px;color:var(--c);font-weight:600;white-space:nowrap}
.gx .frees .fb{flex:none;width:54px}
.gx .frees .wy{margin:3px 0 0 28px;font-size:11px;color:#e66767;overflow-wrap:anywhere}
@container (min-width:900px){
 .gx .tile .k{font-size:12px}.gx .tile .s{font-size:12.5px}
 .gx .tile .v{font-size:30px}.gx .tile.stat .v{font-size:46px}.gx .tile .v small{font-size:15px}
 .gx .tile .v .ic{width:26px;height:26px;font-size:15px}
}
@container (max-width:640px){
 .gx .tile.pick{grid-column:span 12}
